package solution

import (
	"encoding/json"
	"errors"
	"reflect"
	"sort"
	"sync"
)

type Registry struct {
	mu   sync.RWMutex
	data map[string][]byte
}

func NewRegistry() *Registry {
	return &Registry{data: make(map[string][]byte)}
}

func (r *Registry) Put(key string, value any) error {
	if key == "" {
		return errors.New("empty key")
	}
	encoded, err := json.Marshal(value)
	if err != nil {
		return err
	}
	stored := append([]byte(nil), encoded...)
	r.mu.Lock()
	if r.data == nil {
		r.data = make(map[string][]byte)
	}
	r.data[key] = stored
	r.mu.Unlock()
	return nil
}

func (r *Registry) Get(key string, dst any) (bool, error) {
	if key == "" {
		return false, errors.New("empty key")
	}
	if dst == nil {
		return false, errors.New("nil destination")
	}
	destination := reflect.ValueOf(dst)
	if destination.Kind() != reflect.Ptr || destination.IsNil() {
		return false, errors.New("destination must be a non-nil pointer")
	}
	r.mu.RLock()
	encoded, ok := r.data[key]
	copyOfValue := append([]byte(nil), encoded...)
	r.mu.RUnlock()
	if !ok {
		return false, nil
	}
	if err := json.Unmarshal(copyOfValue, dst); err != nil {
		return true, err
	}
	return true, nil
}

func (r *Registry) Delete(key string) bool {
	if key == "" {
		return false
	}
	r.mu.Lock()
	_, ok := r.data[key]
	if ok {
		delete(r.data, key)
	}
	r.mu.Unlock()
	return ok
}

func (r *Registry) Has(key string) bool {
	if key == "" {
		return false
	}
	r.mu.RLock()
	_, ok := r.data[key]
	r.mu.RUnlock()
	return ok
}

func (r *Registry) Keys() []string {
	r.mu.RLock()
	keys := make([]string, 0, len(r.data))
	for key := range r.data {
		keys = append(keys, key)
	}
	r.mu.RUnlock()
	sort.Strings(keys)
	return keys
}
